66	         *  today counting as 0.00. */
67	        public BigDecimal totalShare() {
68	            return members.stream().map(Member::counted).reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
69	        }
70	
71	        /** Balanced when the shares total exactly 100.00. */
72	        public boolean balanced() {
73	            return totalShare().compareTo(FULL) == 0;
74	        }
75	
76	        /** Each member's cut of the pot, in the order of the members; none (null) when there is no pot or the pool
77	         *  is not balanced. A cut is the pot times the share over the shares of the members with a cut added up,
78	         *  rounded half to even to two decimals, 0.00 for a retired member, one held on the sheet's today or one whose
79	         *  dates do not include it (shown as no cut); what the
80	         *  cuts fall short of (or over) the pot goes to the member with the smallest non-zero cut, the latest
81	         *  added on a tie (the last member with a cut when no cut is non-zero), so the cuts total exactly the pot. When every member is retired there are none; when no
82	         *  member otherwise has a cut, each is 0.00. */
83	        public List<BigDecimal> cuts() {
84	            if (pot == null || !balanced() || (!members.isEmpty() && members.stream().allMatch(Member::retired))) {
85	                return null;
86	            }
87	            BigDecimal withCut = members.stream().map(Member::cutShare)
88	                    .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
89	            if (withCut.signum() == 0) {
90	                return new ArrayList<>(members.stream().map(m -> BigDecimal.ZERO.setScale(2)).toList());
91	            }
92	            List<BigDecimal> cuts = new ArrayList<>(members.stream()
93	                    .map(m -> pot.multiply(m.cutShare()).divide(withCut, 2, RoundingMode.HALF_EVEN)).toList());
94	            BigDecimal remainder = pot.subtract(cuts.stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add));
95	            int smallest = -1;
96	            int lastWithShare = -1;
97	            for (int i = 0; i < members.size(); i++) {
98	                if (members.get(i).cutShare().signum() == 0) {
99	                    continue;
100	                }
101	                lastWithShare = i;
102	                if (cuts.get(i).signum() != 0
103	                        && (smallest < 0 || cuts.get(i).compareTo(cuts.get(smallest)) <= 0)) {
104	                    smallest = i;
105	                }
106	            }
107	            int to = smallest >= 0 ? smallest : lastWithShare;
108	            cuts.set(to, cuts.get(to).add(remainder));
109	            return cuts;
110	        }
111	    }
